[ExtensionOf(classstr(WhsrfControlData))]
final class AVAWhsrfControlDataCls_Extension
{

}

Method.Source:
/// <summary>
/// WHSRFControlData_processedControl
/// </summary>
/// <param name="_control">_control</param>
[SubscribesTo(classStr(WHSRFControlData), delegateStr(WHSRFControlData, processedControl))]
public static void WHSRFControlData_processedControl(WhsControl _control)
{ 
    WhsControlContext context = _control.parmContext();
    WhsrfControlData controlData = context.controlData;
    WHSRFPassthrough fieldValues = controlData.parmFieldValues();

    #AVAWHSRF
    #WHSRF
    switch (_control.parmName())
    {
        case #AVAWHSreceivingSO:
            if (SalesTable::find(_control.parmData()).RecId != 0)
            {
                fieldValues.insert(#AVAWHSreceivingSO, _control.parmData());
                fieldValues.insert(#RMANum, _control.parmData());
                controlData.parmFieldValues(fieldValues);
            }
            else
            {
                _control.fail("@WAX3262");
            }
            break;
    }
}
